/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
f=d[0]
def dump(x0,x1,y0,y1):
    for y in range(y0,y1):
        line=[]
        for x in range(x0,x1):
            r,g,b=f[y,x]
            if r>200 and r-g>40 and r-b>40: line.append('P')
            elif b>150 and b>r+20: line.append('B')
            elif r>200 and g>200 and b>200: line.append('w')
            elif r<80 and g<80 and b<80: line.append('#')
            else: line.append('.')
        print(''.join(line))
print('pink start region')
dump(128,150,60,76)
\""
